package com.fasterxml.jackson.core.util;

import com.fasterxml.jackson.core.io.NumberInput;
import java.io.*;
import java.lang.reflect.Field;
import java.math.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import org.junit.*;
import org.junit.Assert;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class TextBuffer_expandCurrentSegment_TriageGen1Test {

    private TextBuffer textBuffer;
    private static final int MAX_SEGMENT_LEN = 1024; // Assuming this value based on typical Jackson constants

    @Before
    public void setUp() {
        // BufferRecycler is typically provided by Jackson's context, 
        // but we can use null or a mock if the constructor allows.
        textBuffer = new TextBuffer(null);
    }

    /**
     * Helper to set the private _currentSegment field via reflection 
     * to simulate specific internal states for testing.
     */
    private void setInternalSegment(char[] segment) throws Exception {
        Field field = TextBuffer.class.getDeclaredField("_currentSegment");
        field.setAccessible(true);
        field.set(textBuffer, segment);
    }

    /**
     * Helper to set the private MAX_SEGMENT_LEN field via reflection 
     * to ensure the test is deterministic regardless of the actual library version.
     */
    private void setMaxSegmentLen(int value) throws Exception {
        Field field = TextBuffer.class.getDeclaredField("MAX_SEGMENT_LEN");
        field.setAccessible(true);
        field.set(textBuffer, value);
    }

    @Test
    public void testExpandCurrentSegment_GrowthBy50Percent() throws Exception {
        // Setup: segment of size 10
        int initialLen = 10;
        char[] initialSegment = new char[initialLen];
        setInternalSegment(initialSegment);

        // Expected: 10 + (10 >> 1) = 10 + 5 = 15
        int expectedLen = 15;

        char[] result = textBuffer.expandCurrentSegment();

        Assert.assertEquals(expectedLen, result.length);
        Assert.assertEquals(expectedLen, textBuffer.getCurrentSegment().length);
    }

    @Test
    public void testExpandCurrentSegment_CapAtMaxSegmentLen() throws Exception {
        // Setup: segment is large, e.g., 800, and MAX_SEGMENT_LEN is 1024
        int initialLen = 800;
        char[] initialSegment = new char[initialLen];
        setInternalSegment(initialSegment);

        // 800 + (800 >> 1) = 1200. 
        // Math.min(1024, 1200) should return 1024.
        int expectedLen = 1024; 

        char[] result = textBuffer.expandCurrentSegment();

        Assert.assertEquals(expectedLen, result.length);
    }

    @Test
    public void testExpandCurrentSegment_WhenAtMaxSegmentLen() throws Exception {
        // Setup: segment is exactly at MAX_SEGMENT_LEN
        int initialLen = 1024;
        char[] initialSegment = new char[initialLen];
        setInternalSegment(initialSegment);

        // According to logic: (len == MAX_SEGMENT_LEN) ? (MAX_SEGMENT_LEN + 1) : ...
        // This branch covers the ternary operator for the "above intended maximum" case.
        int expectedLen = 1025;

        char[] result = textBuffer.expandCurrentSegment();

        Assert.assertEquals(expectedLen, result.length);
    }

    @Test
    public void testExpandCurrentSegment_SmallSegment() throws Exception {
        // Setup: very small segment
        int initialLen = 1;
        char[] initialSegment = new char[initialLen];
        setInternalSegment(initialSegment);

        // 1 + (1 >> 1) = 1 + 0 = 1. 
        // Note: In real Jackson, this might cause an infinite loop if not careful, 
        // but we are testing the code as written.
        int expectedLen = 1;

        char[] result = textBuffer.expandCurrentSegment();

        Assert.assertEquals(expectedLen, result.length);
    }

    @Test
    public void testExpandCurrentSegment_ZeroLength() throws Exception {
        // Setup: segment length 0
        int initialLen = 0;
        char[] initialSegment = new char[initialLen];
        setInternalSegment(initialSegment);

        // 0 + (0 >> 1) = 0
        int expectedLen = 0;

        char[] result = textBuffer.expandCurrentSegment();

        Assert.assertEquals(expectedLen, result.length);
    }
}
